class Solution {
public:
    int maximumMinimumPath(vector<vector<int>>& grid) {
        int R = grid.size(), C = grid[0].size();
        priority_queue<tuple<int, int, int>> pq;
        vector<vector<bool>> visited(R, vector<bool>(C, false));
        pq.push({grid[0][0], 0, 0});
        visited[0][0] = true;
        int min_val = grid[0][0];
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!pq.empty()) {
            auto [val, r, c] = pq.top();
            pq.pop();
            min_val = min(min_val, val);
            if (r == R - 1 && c == C - 1) return min_val;

            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    pq.push({grid[nr][nc], nr, nc});
                }
            }
        }
        return min_val;
    }
};

import java.util.*;

class Solution {
    public int maximumMinimumPath(int[][] grid) {
        int R = grid.length, C = grid[0].length;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        boolean[][] visited = new boolean[R][C];
        pq.offer(new int[]{grid[0][0], 0, 0});
        visited[0][0] = true;
        int minVal = grid[0][0];
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int val = top[0], r = top[1], c = top[2];
            minVal = Math.min(minVal, val);
            if (r == R - 1 && c == C - 1) return minVal;

            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    pq.offer(new int[]{grid[nr][nc], nr, nc});
                }
            }
        }
        return minVal;
    }
}

var maximumMinimumPath = function(grid) {
    const R = grid.length, C = grid[0].length;
    const heap = [];
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] < heap[i][0]) {
                [heap[p], heap[i]] = [heap[i], heap[p]];
                i = p;
            } else break;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < heap.length && heap[l][0] > heap[best][0]) best = l;
                if (r < heap.length && heap[r][0] > heap[best][0]) best = r;
                if (best !== i) {
                    [heap[i], heap[best]] = [heap[best], heap[i]];
                    i = best;
                } else break;
            }
        }
        return top;
    };

    const visited = Array.from({ length: R }, () => new Array(C).fill(false));
    push([grid[0][0], 0, 0]);
    visited[0][0] = true;
    let minVal = grid[0][0];
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    while (heap.length > 0) {
        const [val, r, c] = pop();
        minVal = Math.min(minVal, val);
        if (r === R - 1 && c === C - 1) return minVal;

        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc]) {
                visited[nr][nc] = true;
                push([grid[nr][nc], nr, nc]);
            }
        }
    }
    return minVal;
};
